create extension if not exists "pgcrypto";
create type public.account_status as enum ('PENDING','APPROVED','REJECTED','SUSPENDED');
create type public.app_role as enum ('TRAINEE','TRAINER','ADMIN');
create type public.course_status as enum ('DRAFT','REVIEW','PUBLISHED','ARCHIVED');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique not null,full_name text not null,designation text,department text,location text,bio text,years_experience numeric default 0,status public.account_status not null default 'PENDING',qualifications text[] default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid primary key references public.profiles(id) on delete cascade,role public.app_role not null,assigned_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.skills(id uuid primary key default gen_random_uuid(),name text unique not null,category text,canonical_slug text unique not null);
create table public.user_skills(user_id uuid references public.profiles(id) on delete cascade,skill_id uuid references public.skills(id) on delete cascade,proficiency int check(proficiency between 1 and 5),years numeric default 0,evidence text,primary key(user_id,skill_id));
create table public.trainer_competencies(id uuid primary key default gen_random_uuid(),trainer_id uuid references public.profiles(id) on delete cascade,skill_id uuid references public.skills(id),relevant_years numeric default 0,qualification_match numeric default .7,performance numeric default .75,availability numeric default .8,certifications numeric default .7,rating numeric default 4.5,unique(trainer_id,skill_id));
create table public.courses(id uuid primary key default gen_random_uuid(),code text unique not null,title text not null,description text,category text,level text,duration_hours numeric,owner_id uuid references public.profiles(id),status public.course_status default 'DRAFT',self_enrollable boolean default true,competency_tags text[] default '{}',created_at timestamptz default now(),updated_at timestamptz default now());
create table public.course_modules(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses(id) on delete cascade,title text not null,description text,order_index int not null,created_at timestamptz default now());
create table public.course_resources(id uuid primary key default gen_random_uuid(),module_id uuid references public.course_modules(id) on delete cascade,owner_id uuid references public.profiles(id),title text not null,type text check(type in ('VIDEO','PDF','PPT','NOTES','LINK')),storage_path text,description text,visibility text default 'PUBLISHED',created_at timestamptz default now());
create table public.enrollments(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses(id) on delete cascade,trainee_id uuid references public.profiles(id) on delete cascade,status text default 'ENROLLED',progress numeric default 0 check(progress between 0 and 100),enrolled_at timestamptz default now(),completed_at timestamptz,unique(course_id,trainee_id));
create table public.learning_progress(id uuid primary key default gen_random_uuid(),enrollment_id uuid references public.enrollments(id) on delete cascade,module_id uuid references public.course_modules(id) on delete cascade,completed boolean default false,updated_at timestamptz default now(),unique(enrollment_id,module_id));
create table public.assessments(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses(id) on delete cascade,trainer_id uuid references public.profiles(id),title text not null,deadline timestamptz,duration_minutes int default 20,passing_percent numeric default 70,attempts_allowed int default 1,status text default 'DRAFT');
create table public.questions(id uuid primary key default gen_random_uuid(),assessment_id uuid references public.assessments(id) on delete cascade,prompt text not null,options jsonb not null,correct_option int not null,marks numeric default 1,topic text,difficulty text);
create table public.assessment_attempts(id uuid primary key default gen_random_uuid(),assessment_id uuid references public.assessments(id),trainee_id uuid references public.profiles(id),started_at timestamptz default now(),submitted_at timestamptz,score numeric,status text default 'IN_PROGRESS',unique(assessment_id,trainee_id));
create table public.assessment_answers(id uuid primary key default gen_random_uuid(),attempt_id uuid references public.assessment_attempts(id) on delete cascade,question_id uuid references public.questions(id),selected_option int,awarded_marks numeric default 0,unique(attempt_id,question_id));
create table public.certificates(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses(id),trainee_id uuid references public.profiles(id),certificate_no text unique not null,issued_at timestamptz default now(),status text default 'VALID');
create table public.feedback(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses(id),trainee_id uuid references public.profiles(id),trainer_rating int check(trainer_rating between 1 and 5),content_rating int check(content_rating between 1 and 5),relevance_rating int check(relevance_rating between 1 and 5),comments text,created_at timestamptz default now(),unique(course_id,trainee_id));
create table public.announcements(id uuid primary key default gen_random_uuid(),author_id uuid references public.profiles(id),title text not null,body text not null,category text default 'NOTICE',priority text default 'NORMAL',audience text default 'ALL',publish_from timestamptz default now(),publish_to timestamptz,pinned boolean default false,created_at timestamptz default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),action text not null,target_type text,target_id uuid,metadata jsonb default '{}',created_at timestamptz default now());
create index enrollments_trainee_idx on public.enrollments(trainee_id); create index courses_owner_idx on public.courses(owner_id); create index announcements_window_idx on public.announcements(publish_from,publish_to);
create view public.trainer_competency_view as select p.id,p.full_name as name,p.status,array_agg(distinct s.name) as skills,max(tc.relevant_years) as relevant_years,avg(tc.qualification_match) as qualification_match,avg(tc.performance) as performance,avg(tc.availability) as availability,avg(tc.certifications) as certifications,avg(tc.rating) as rating from profiles p join user_roles ur on ur.user_id=p.id and ur.role='TRAINER' left join trainer_competencies tc on tc.trainer_id=p.id left join skills s on s.id=tc.skill_id group by p.id,p.full_name,p.status;
alter table public.profiles enable row level security; alter table public.courses enable row level security; alter table public.enrollments enable row level security; alter table public.learning_progress enable row level security; alter table public.announcements enable row level security;
create policy "approved users see published courses" on public.courses for select using (status='PUBLISHED' and exists(select 1 from profiles where id=auth.uid() and status='APPROVED'));
create policy "users see own profile" on public.profiles for select using (id=auth.uid()); create policy "users update own profile" on public.profiles for update using (id=auth.uid());
create policy "trainees manage own enrollments" on public.enrollments for all using (trainee_id=auth.uid()) with check (trainee_id=auth.uid());
create policy "users see current announcements" on public.announcements for select using (publish_from<=now() and (publish_to is null or publish_to>=now()));
